def lengthOfLongestSubstring(s, result=0, count=0):
    """
    :type s: str
    :rtype: int
    """
    
    if len(s) == 0:
        return 0 

    sList = list(s)
    p2=1
    seen = str(sList[0])
    result = 1
    
    while p2 < len(s):
        if sList[p2] not in seen:
            seen += sList[p2]
            result = max(result, len(seen))
            p2 += 1
        else:
            seen = seen.split(sList[p2],1)[1] + sList[p2] 
            result = max(result, len(seen))
            p2+=1                     
    return result

print(lengthOfLongestSubstring(s))



